head.script:
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 경력및기술 탭 부분을 클릭하여 editor의 높이와 넓이가 정상인지 확인한다.
    //1. Run the sample file and click on the Career and Technology tab to see if the height and width of the editor are normal.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1_tab_tabs2').click()");
    // verify setp 1. 샘플파일을 실행 후 경력및기술 탭 부분을 클릭하여 editor의 높이와 넓이가 화면에 맞게 보여진다.
    // 1. After running the sample file, click on the Career and Technology tab to view the height and width of the editor.
    WebSquare.wUnit.addCommand("assert", "scwin.checkWidth()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.checkWidth = function() {
	var ret = false;
	if (CKEDITOR.EDITOR_MAJOR_VERSION == '5') {
		width1 = window.getComputedStyle(document.getElementsByClassName('w2editor')[0]).width;
		width2 = window.getComputedStyle(document.getElementsByClassName('ck-editor')[0]).width;
		if (width1 == width2) {
			ret = true;
		}
	} else {
		width = WebSquare.wUnit.getObjById('cke_'+$p.id+'edi_sResume_').style.width;
		if (width == '100%') {
			ret = true;
		}
	}
	return ret;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 23-Jan-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
